import pandas as pd
import dateutil.parser

class DataNormalizer:
    def __init__(self, df: pd.DataFrame):
        self.df = df

    def normalize_dates(self, column_name: str, date_format: str = '%Y-%m-%d') -> pd.Series:
        """Normalize date values in a column to a standard format"""
        return self.df[column_name].apply(dateutil.parser.parse).dt.strftime(date_format)

    def normalize_categoricals(self, column_name: str) -> pd.Series:
        """One-hot encode categorical values in a column"""
        return pd.get_dummies(self.df[column_name])

    def normalize_numerics(self, column_name: str, min_value: float = 0, max_value: float = 1) -> pd.Series:
        """Scale numeric values in a column to a standard range"""
        return (self.df[column_name] - self.df[column_name].min()) / (self.df[column_name].max() - self.df[column_name].min()) * (max_value - min_value) + min_value
```

